1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io/fs"
9		"os"
10		"os/exec"
11		"path/filepath"
12		"strings"
13		"time"
14	)
15	
16	const (
17		secretsFileMode = 0o600
18		secretsDirMode  = 0o700
19		// gitCheckTimeout bounds the one git process the store may start.
20		gitCheckTimeout = 10 * time.Second
21	)
22	
23	// Secrets are the passwords of the bench. They live in the secrets file and
24	// nowhere else: not in the descriptor, not in a manifest, not in an error.
25	type Secrets struct {
26		// AdminPassword is the current password of the admin account.
27		AdminPassword string `json:"adminPassword"`
28		// PendingAdminPassword is the new admin password, written before it is sent
29		// to Nexus so that an interrupted change does not lose it.
30		PendingAdminPassword string `json:"pendingAdminPassword,omitempty"`
31		// PullPassword is the password of the read-only bench-pull account.
32		PullPassword string `json:"pullPassword,omitempty"`
33	}
34	
35	// SecretStore keeps the Secrets of one bench (one context and namespace).
36	type SecretStore interface {
37		// Load returns the stored secrets; found is false, without an error, when
38		// nothing is stored yet.
39		Load() (s Secrets, found bool, err error)
40		// Save replaces the stored secrets atomically.
41		Save(Secrets) error
42		// Remove deletes the stored secrets. It succeeds when there are none.
43		Remove() error
44	}
45	
46	// DefaultSecretsPath returns where the secrets of a bench live:
47	// <state>/devdesk/nexus-bench/<context>/<namespace>/secrets.json, with <state>
48	// the XDG_STATE_HOME variable, else ~/.local/state. The folder is outside every
49	// repository and shared by all the worktrees of the project. getenv is os.Getenv
50	// in production; an empty variable counts as unset.
51	func DefaultSecretsPath(kubeContext, namespace string, getenv func(string) string) (string, error) {
52		for _, part := range []string{kubeContext, namespace} {
53			if part == "" || part == "." || part == ".." || strings.ContainsAny(part, `/\`) {
54				return "", fmt.Errorf("%q cannot name a folder of the secrets path", part)
55			}
56		}
57		state := getenv("XDG_STATE_HOME")
58		if state == "" {
59			home := getenv("HOME")
60			if home == "" {
61				home = getenv("USERPROFILE")
62			}
63			if home == "" {
64				return "", errors.New("cannot place the secrets file: neither XDG_STATE_HOME nor HOME is set; set NEXUS_BENCH_SECRETS to a path outside the repository")
65			}
66			state = filepath.Join(home, ".local", "state")
67		}
68		return filepath.Join(state, "devdesk", "nexus-bench", kubeContext, namespace, "secrets.json"), nil
69	}
70	
71	// fileStore is the SecretStore backed by one JSON file.
72	type fileStore struct{ path string }
73	
74	// NewFileStore returns the store of the file at path. It touches nothing on
75	// disk. A path inside a git working tree is refused unless git ignores it, so
76	// that a secret cannot be committed by accident; a path outside every
77	// repository is accepted without asking git.
78	func NewFileStore(path string) (SecretStore, error) {
79		if path == "" {
80			return nil, errors.New("the secrets path is empty")
81		}
82		abs, err := filepath.Abs(path)
83		if err != nil {
84			return nil, fmt.Errorf("resolve the secrets path: %w", err)
85		}
86		if root, inRepo := findGitRoot(filepath.Dir(abs)); inRepo {
87			ignored, err := gitIgnores(root, abs)
88			if err != nil {
89				return nil, &BenchError{
90					Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and git could not tell whether it is ignored", abs, root),
91					Check: "run git check-ignore -v on that path, or set NEXUS_BENCH_SECRETS to a path outside the repository",
92					Err:   err,
93				}
94			}
95			if !ignored {
96				return nil, &BenchError{
97					Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and is not ignored by git, so the passwords could be committed", abs, root),
98					Check: "set NEXUS_BENCH_SECRETS to a path outside the repository, or add the file to .gitignore",
99				}
100			}
101		}
102		return &fileStore{path: abs}, nil
103	}
104	
105	// findGitRoot walks up from dir (which may not exist yet) to the first folder
106	// that holds a .git entry, a directory or a file as in a worktree.
107	func findGitRoot(dir string) (root string, ok bool) {
108		for {
109			if _, err := os.Lstat(filepath.Join(dir, ".git")); err == nil {
110				return dir, true
111			}
112			parent := filepath.Dir(dir)
113			if parent == dir {
114				return "", false
115			}
116			dir = parent
117		}
118	}
119	
120	// gitIgnores reports whether git ignores path inside the working tree at root.
121	// It is a variable so a test can replace the one process the package starts for
122	// the guard; kubectl.go stays the only file that starts one otherwise.
123	var gitIgnores = func(root, path string) (bool, error) {
124		ctx, cancel := context.WithTimeout(context.Background(), gitCheckTimeout)
125		defer cancel()
126		cmd := exec.CommandContext(ctx, "git", "-C", root, "check-ignore", "-q", "--", path) //nolint:gosec // fixed arguments, the paths come from the caller's own configuration
127		err := cmd.Run()
128		if err == nil {
129			return true, nil // exit 0: the path is ignored
130		}
131		var exit *exec.ExitError
132		if errors.As(err, &exit) && exit.ExitCode() == 1 {
133			return false, nil // exit 1: the path is not ignored
134		}
135		return false, err // git missing, exit 128 (not a repository, bad path), timeout
136	}
137	
138	// Load implements SecretStore. The error never carries the content of the
139	// file: a corrupt file may hold a password.
140	func (s *fileStore) Load() (Secrets, bool, error) {
141		data, err := os.ReadFile(s.path)
142		if errors.Is(err, fs.ErrNotExist) {
143			return Secrets{}, false, nil
144		}
145		if err != nil {
146			return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
147		}
148		var out Secrets
149		if err := json.Unmarshal(data, &out); err != nil {
150			return Secrets{}, false, &BenchError{
151				Cause: fmt.Sprintf("the secrets file %s is not valid", s.path),
152				Check: "delete the file and run the bench again, or restore it from a copy; its content is not shown",
153				Err:   err,
154			}
155		}
156		return out, true, nil
157	}
158	
159	// Save implements SecretStore.
160	func (s *fileStore) Save(secrets Secrets) error {
161		data, err := json.MarshalIndent(secrets, "", "  ")
162		if err != nil {
163			return fmt.Errorf("encode the secrets: %w", err)
164		}
165		return writeFileAtomic(s.path, append(data, '\n'), secretsFileMode, secretsDirMode)
166	}
167	
168	// Remove implements SecretStore. It deletes the file, then its folder when
169	// that is empty; a folder that holds anything else stays.
170	func (s *fileStore) Remove() error {
171		if err := os.Remove(s.path); err != nil && !errors.Is(err, fs.ErrNotExist) {
172			return fmt.Errorf("remove the secrets file: %w", err)
173		}
174		dir := filepath.Dir(s.path)
175		entries, err := os.ReadDir(dir)
176		if errors.Is(err, fs.ErrNotExist) || (err == nil && len(entries) > 0) {
177			return nil
178		}
179		if err != nil {
180			return fmt.Errorf("read the secrets folder: %w", err)
181		}
182		if err := os.Remove(dir); err != nil && !errors.Is(err, fs.ErrNotExist) {
183			return fmt.Errorf("remove the secrets folder: %w", err)
184		}
185		return nil
186	}
187	
188	// writeFileAtomic writes data to path through a temporary file of the same
189	// folder and a rename, so a reader sees the old file or the new one, never a
190	// partial one. Missing folders are created with dirMode. The temporary file is
191	// removed when anything fails. The error text holds paths, never data.
192	func writeFileAtomic(path string, data []byte, fileMode, dirMode os.FileMode) (err error) {
193		dir := filepath.Dir(path)
194		if err := os.MkdirAll(dir, dirMode); err != nil {
195			return fmt.Errorf("create the folder %s: %w", dir, err)
196		}
197		tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*.tmp")
198		if err != nil {
199			return fmt.Errorf("create a temporary file in %s: %w", dir, err)
200		}
201		defer func() {
202			if err != nil {
203				_ = tmp.Close()
204				_ = os.Remove(tmp.Name())
205			}
206		}()
207		if _, err = tmp.Write(data); err != nil {
208			return fmt.Errorf("write %s: %w", tmp.Name(), err)
209		}
210		if err = tmp.Chmod(fileMode); err != nil {
211			return fmt.Errorf("set the mode of %s: %w", tmp.Name(), err)
212		}
213		if err = tmp.Sync(); err != nil {
214			return fmt.Errorf("sync %s: %w", tmp.Name(), err)
215		}
216		if err = tmp.Close(); err != nil {
217			return fmt.Errorf("close %s: %w", tmp.Name(), err)
218		}
219		if err = os.Rename(tmp.Name(), path); err != nil {
220			return fmt.Errorf("replace %s: %w", path, err)
221		}
222		return nil
223	}
