1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"slices"
8		"strings"
9	)
10	
11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20	)
21	
22	// PreflightResult is what a successful preflight learned about the cluster.
23	type PreflightResult struct {
24		// NamespaceExists is true when the bench namespace is there.
25		NamespaceExists bool
26		// NamespaceOurs is true when it carries our managed-by label.
27		NamespaceOurs bool
28		// NodeIP is the InternalIP of the first node that reports one; empty when
29		// none does, which is not an error (the other hosts still work). It is not
30		// read for OpDown.
31		NodeIP string
32	}
33	
34	const (
35		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
36		// puts on the namespace; down deletes a namespace only when it carries it.
37		managedByLabel = "app.kubernetes.io/managed-by"
38		managedByValue = "devdesk-nexus-bench"
39	
40		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
41		nexusServiceName = "nexus"
42	
43		// requestTimeout bounds every call that reaches the API server.
44		requestTimeout = "--request-timeout=10s"
45	)
46	
47	// permissionScope says where a can-i question applies.
48	type permissionScope int
49	
50	const (
51		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
52		scopeNamespace                        // -n <namespace>
53		scopeAll                              // -A
54	)
55	
56	// permission is one "kubectl auth can-i" question the preflight asks.
57	type permission struct {
58		verb, resource string
59		scope          permissionScope
60	}
61	
62	// permissionsByOp is the list F2 of the plan: what each operation needs. An
63	// operation absent from the map (status) writes nothing and asks nothing.
64	var permissionsByOp = map[Op][]permission{
65		OpUp: {
66			{"create", "namespaces", scopeCluster},
67			{"create", "persistentvolumeclaims", scopeNamespace},
68			{"create", "services", scopeNamespace},
69			{"create", "deployments", scopeNamespace},
70			{"create", "secrets", scopeNamespace},
71			{"create", "pods/exec", scopeNamespace},
72			{"list", "services", scopeAll},
73		},
74		OpProvision: {{"create", "pods/exec", scopeNamespace}},
75		OpDown:      {{"delete", "namespaces", scopeCluster}},
76	}
77	
78	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
79	// returns what it learned. Nothing is written to the cluster, whatever the
80	// outcome: a failure here means no write was ever issued. The checks run in a
81	// fixed order and stop at the first failure, so nothing is asked of a cluster
82	// the context does not reach:
83	//
84	//  1. the parameters (no call at all)
85	//  2. the context is in the kubeconfig
86	//  3. the API server answers /readyz
87	//  4. the can-i questions of the operation
88	//  5. the namespace: absent, ours, or foreign
89	//  6. up only: no other Service holds one of our NodePorts
90	//  7. all but down: the InternalIP of the node
91	//
92	// Every failure is a *BenchError.
93	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
94		var res PreflightResult
95		if err := p.Validate(); err != nil {
96			return res, err
97		}
98		pf := preflight{r: r, p: p}
99		if err := pf.checkContext(ctx); err != nil {
100			return res, err
101		}
102		if err := pf.checkReachable(ctx); err != nil {
103			return res, err
104		}
105		for _, perm := range permissionsByOp[op] {
106			if err := pf.checkPermission(ctx, perm); err != nil {
107				return res, err
108			}
109		}
110		res, err := pf.checkNamespace(ctx, op)
111		if err != nil {
112			return res, err
113		}
114		if op == OpUp {
115			if err := pf.checkNodePorts(ctx); err != nil {
116				return res, err
117			}
118		}
119		if op != OpDown {
120			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
121				return res, err
122			}
123		}
124		return res, nil
125	}
126	
127	type preflight struct {
128		r Runner
129		p Params
130	}
131	
132	// local runs a call that does not reach the API server.
133	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
134		out, errOut, err := pf.r.Run(ctx, nil, args...)
135		return string(out), string(errOut), err
136	}
137	
138	// remote runs a call that reaches the API server, under a request timeout.
139	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
140		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
141	}
142	
143	// command is the kubectl command line a user can run to repeat a call.
144	func (pf preflight) command(args ...string) string {
145		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
146	}
147	
148	// failure turns a failed kubectl call into a BenchError whose kind comes from
149	// the stderr. Neither the stderr nor the sub-process error reaches the message.
150	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
151		kind := classifyKubectl(stderr)
152		reason := "kubectl failed"
153		switch kind {
154		case Forbidden:
155			reason = "the API server refused the request (forbidden)"
156		case ClusterUnreachable:
157			reason = "the cluster did not answer"
158		}
159		return &BenchError{
160			Kind:  kind,
161			Cause: "could not " + what + ": " + reason,
162			Check: pf.command(args...),
163			Err:   err,
164		}
165	}
166	
167	func (pf preflight) checkContext(ctx context.Context) error {
168		args := []string{"config", "get-contexts", "-o", "name"}
169		out, errOut, err := pf.local(ctx, args...)
170		if err != nil {
171			return pf.failure("list the kubeconfig contexts", args, errOut, err)
172		}
173		for _, line := range strings.Split(out, "\n") {
174			if strings.TrimSpace(line) == pf.p.Context {
175				return nil
176			}
177		}
178		return &BenchError{
179			Kind:  ContextNotFound,
180			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
181			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
182		}
183	}
184	
185	func (pf preflight) checkReachable(ctx context.Context) error {
186		args := []string{"get", "--raw", "/readyz"}
187		_, _, err := pf.remote(ctx, args...)
188		if err == nil {
189			return nil
190		}
191		return &BenchError{
192			Kind:  ClusterUnreachable,
193			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
194			Check: pf.command(args...),
195			Err:   err,
196		}
197	}
198	
199	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
200	// non-zero exit, so the answer is read before the error.
201	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
202		args := []string{"auth", "can-i", perm.verb, perm.resource}
203		where := "cluster-wide"
204		switch perm.scope {
205		case scopeNamespace:
206			args = append(args, "-n", pf.p.Namespace)
207			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
208		case scopeAll:
209			args = append(args, "-A")
210			where = "in all namespaces"
211		}
212		out, errOut, err := pf.remote(ctx, args...)
213		answer := strings.TrimSpace(out)
214		switch {
215		case strings.HasPrefix(answer, "no"):
216			return &BenchError{
217				Kind:  Forbidden,
218				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
219				Check: pf.command(args...),
220				Err:   err,
221			}
222		case err == nil && strings.HasPrefix(answer, "yes"):
223			return nil
224		}
225		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
226	}
227	
228	// namespaceObject is the part of a Namespace the preflight reads.
229	type namespaceObject struct {
230		Metadata struct {
231			Labels map[string]string `json:"labels"`
232		} `json:"metadata"`
233	}
234	
235	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
236		var res PreflightResult
237		ns := pf.p.Namespace
238		args := []string{"get", "namespace", ns, "-o", "json"}
239		out, errOut, err := pf.remote(ctx, args...)
240		switch {
241		case err != nil && isNotFound(errOut):
242			// Absent: only provision and status need it.
243			if op == OpProvision || op == OpStatus {
244				return res, &BenchError{
245					Kind:  NamespaceMissing,
246					Cause: fmt.Sprintf("namespace %q does not exist", ns),
247					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
248					Err:   err,
249				}
250			}
251			return res, nil
252		case err != nil:
253			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
254		}
255	
256		var obj namespaceObject
257		if err := json.Unmarshal([]byte(out), &obj); err != nil {
258			return res, &BenchError{
259				Kind:  Unclassified,
260				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
261				Check: pf.command(args...),
262				Err:   err,
263			}
264		}
265		res.NamespaceExists = true
266		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
267		if !res.NamespaceOurs {
268			return res, &BenchError{
269				Kind:  NamespaceForeign,
270				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
271				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
272			}
273		}
274		return res, nil
275	}
276	
277	// serviceList is the part of a Service list the preflight reads.
278	type serviceList struct {
279		Items []struct {
280			Metadata struct {
281				Name      string `json:"name"`
282				Namespace string `json:"namespace"`
283			} `json:"metadata"`
284			Spec struct {
285				Ports []struct {
286					NodePort int `json:"nodePort"`
287				} `json:"ports"`
288			} `json:"spec"`
289		} `json:"items"`
290	}
291	
292	// checkNodePorts reads every Service of the cluster: the list of taken
293	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
294	// them: that is a second up.
295	func (pf preflight) checkNodePorts(ctx context.Context) error {
296		args := []string{"get", "services", "-A", "-o", "json"}
297		out, errOut, err := pf.remote(ctx, args...)
298		if err != nil {
299			return pf.failure("list the Services of the cluster", args, errOut, err)
300		}
301		var list serviceList
302		if err := json.Unmarshal([]byte(out), &list); err != nil {
303			return &BenchError{
304				Kind:  Unclassified,
305				Cause: "kubectl answered with something that is not a Service list",
306				Check: pf.command(args...),
307				Err:   err,
308			}
309		}
310		var taken []string
311		for _, svc := range list.Items {
312			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
313				continue
314			}
315			for _, port := range svc.Spec.Ports {
316				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
317					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
318				}
319			}
320		}
321		if len(taken) > 0 {
322			return &BenchError{
323				Kind:  NodePortTaken,
324				Cause: "NodePort " + strings.Join(taken, ", "),
325				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
326			}
327		}
328		return nil
329	}
330	
331	// nodeList is the part of a Node list the preflight reads.
332	type nodeList struct {
333		Items []struct {
334			Status struct {
335				Addresses []struct {
336					Type    string `json:"type"`
337					Address string `json:"address"`
338				} `json:"addresses"`
339			} `json:"status"`
340		} `json:"items"`
341	}
342	
343	// nodeIP returns the first InternalIP any node reports, or "" when none does.
344	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
345		args := []string{"get", "nodes", "-o", "json"}
346		out, errOut, err := pf.remote(ctx, args...)
347		if err != nil {
348			return "", pf.failure("read the nodes", args, errOut, err)
349		}
350		var nodes nodeList
351		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
352			return "", &BenchError{
353				Kind:  Unclassified,
354				Cause: "kubectl answered with something that is not a Node list",
355				Check: pf.command(args...),
356				Err:   err,
357			}
358		}
359		for _, node := range nodes.Items {
360			for _, addr := range node.Status.Addresses {
361				if addr.Type == "InternalIP" {
362					return addr.Address, nil
363				}
364			}
365		}
366		return "", nil
367	}
