167	func (pf preflight) checkContext(ctx context.Context) error {
168		args := []string{"config", "get-contexts", "-o", "name"}
169		out, errOut, err := pf.local(ctx, args...)
170		if err != nil {
171			return pf.failure("list the kubeconfig contexts", args, errOut, err)
172		}
173		for _, line := range strings.Split(out, "\n") {
174			if strings.TrimSpace(line) == pf.p.Context {
175				return nil
176			}
177		}
178		return &BenchError{
179			Kind:  ContextNotFound,
180			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
181			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
182		}
183	}
184	
185	func (pf preflight) checkReachable(ctx context.Context) error {
186		args := []string{"get", "--raw", "/readyz"}
187		_, _, err := pf.remote(ctx, args...)
188		if err == nil {
189			return nil
190		}
191		return &BenchError{
192			Kind:  ClusterUnreachable,
193			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
194			Check: pf.command(args...),
195			Err:   err,
196		}
197	}
