199	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
200	// non-zero exit, so the answer is read before the error.
201	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
202		args := []string{"auth", "can-i", perm.verb, perm.resource}
203		where := "cluster-wide"
204		switch perm.scope {
205		case scopeNamespace:
206			args = append(args, "-n", pf.p.Namespace)
207			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
208		case scopeAll:
209			args = append(args, "-A")
210			where = "in all namespaces"
211		}
212		out, errOut, err := pf.remote(ctx, args...)
213		answer := strings.TrimSpace(out)
214		switch {
215		case strings.HasPrefix(answer, "no"):
216			return &BenchError{
217				Kind:  Forbidden,
218				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
219				Check: pf.command(args...),
220				Err:   err,
221			}
222		case err == nil && strings.HasPrefix(answer, "yes"):
223			return nil
224		}
225		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
226	}
