235	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
236		var res PreflightResult
237		ns := pf.p.Namespace
238		args := []string{"get", "namespace", ns, "-o", "json"}
239		out, errOut, err := pf.remote(ctx, args...)
240		switch {
241		case err != nil && isNotFound(errOut):
242			// Absent: only provision and status need it.
243			if op == OpProvision || op == OpStatus {
244				return res, &BenchError{
245					Kind:  NamespaceMissing,
246					Cause: fmt.Sprintf("namespace %q does not exist", ns),
247					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
248					Err:   err,
249				}
250			}
251			return res, nil
252		case err != nil:
253			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
254		}
255	
256		var obj namespaceObject
257		if err := json.Unmarshal([]byte(out), &obj); err != nil {
258			return res, &BenchError{
259				Kind:  Unclassified,
260				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
261				Check: pf.command(args...),
262				Err:   err,
263			}
264		}
265		res.NamespaceExists = true
266		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
267		if !res.NamespaceOurs {
268			return res, &BenchError{
269				Kind:  NamespaceForeign,
270				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
271				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
272			}
273		}
274		return res, nil
275	}
