292	// checkNodePorts reads every Service of the cluster: the list of taken
293	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
294	// them: that is a second up.
295	func (pf preflight) checkNodePorts(ctx context.Context) error {
296		args := []string{"get", "services", "-A", "-o", "json"}
297		out, errOut, err := pf.remote(ctx, args...)
298		if err != nil {
299			return pf.failure("list the Services of the cluster", args, errOut, err)
300		}
301		var list serviceList
302		if err := json.Unmarshal([]byte(out), &list); err != nil {
303			return &BenchError{
304				Kind:  Unclassified,
305				Cause: "kubectl answered with something that is not a Service list",
306				Check: pf.command(args...),
307				Err:   err,
308			}
309		}
310		var taken []string
311		for _, svc := range list.Items {
312			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
313				continue
314			}
315			for _, port := range svc.Spec.Ports {
316				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
317					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
318				}
319			}
320		}
321		if len(taken) > 0 {
322			return &BenchError{
323				Kind:  NodePortTaken,
324				Cause: "NodePort " + strings.Join(taken, ", "),
325				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
326			}
327		}
328		return nil
329	}
