331	// nodeList is the part of a Node list the preflight reads.
332	type nodeList struct {
333		Items []struct {
334			Status struct {
335				Addresses []struct {
336					Type    string `json:"type"`
337					Address string `json:"address"`
338				} `json:"addresses"`
339			} `json:"status"`
340		} `json:"items"`
341	}
342	
343	// nodeIP returns the first InternalIP any node reports, or "" when none does.
344	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
345		args := []string{"get", "nodes", "-o", "json"}
346		out, errOut, err := pf.remote(ctx, args...)
347		if err != nil {
348			return "", pf.failure("read the nodes", args, errOut, err)
349		}
350		var nodes nodeList
351		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
352			return "", &BenchError{
353				Kind:  Unclassified,
354				Cause: "kubectl answered with something that is not a Node list",
355				Check: pf.command(args...),
356				Err:   err,
357			}
358		}
359		for _, node := range nodes.Items {
360			for _, addr := range node.Status.Addresses {
361				if addr.Type == "InternalIP" {
362					return addr.Address, nil
363				}
364			}
365		}
366		return "", nil
367	}
