783	func TestRunPreflightFails(t *testing.T) {
784		for _, tt := range failCases() {
785			t.Run(tt.name, func(t *testing.T) {
786				p := Defaults()
787				if tt.params != nil {
788					p = tt.params()
789				}
790				f := newFakeKubectl(t, p)
791				tt.setup(f)
792	
793				_, err := RunPreflight(context.Background(), f, p, tt.op)
794				if err == nil {
795					t.Fatal("RunPreflight succeeded, want a refusal")
796				}
797				be := requireCleanError(t, err)
798	
799				if tt.unplanned {
800					for _, k := range namedKinds {
801						if be.Kind == k.kind {
802							t.Errorf("an unplanned failure was classified as %s", k.name)
803						}
804					}
805				} else if be.Kind != tt.kind {
806					t.Errorf("Kind = %d, want %d; message: %v", be.Kind, tt.kind, err)
807				}
808				for _, want := range tt.mention {
809					if !strings.Contains(err.Error(), want) {
810						t.Errorf("message %q does not mention %q", err.Error(), want)
811					}
812				}
813				if tt.onlyCalls != nil {
814					if got := f.callLines(); !slices.Equal(got, tt.onlyCalls) {
815						t.Errorf("calls = %q, want %q (nothing is asked of a cluster the context does not reach)", got, tt.onlyCalls)
816					}
817				}
818				requireReadOnly(t, f)
819			})
820		}
821	}
