379	func TestNewFileStoreGitGuard(t *testing.T) {
380		tests := []struct {
381			name      string
382			gitignore string // content of the repository's .gitignore; "" writes none
383			rel       string // secrets path, relative to the repository
384			wantError bool
385		}{
386			{"in a repository, not ignored: refused", "", filepath.Join("sub", "secrets.json"), true},
387			{"in a repository, at its root, not ignored: refused", "", "secrets.json", true},
388			{"in a repository, ignored by .gitignore: accepted", "secrets.json\n", filepath.Join("sub", "secrets.json"), false},
389			{"in a repository, another pattern ignored: still refused", "other.json\n", filepath.Join("sub", "secrets.json"), true},
390		}
391		for _, tt := range tests {
392			t.Run(tt.name, func(t *testing.T) {
393				repo := gitRepo(t)
394				if tt.gitignore != "" {
395					if err := os.WriteFile(filepath.Join(repo, ".gitignore"), []byte(tt.gitignore), 0o644); err != nil {
396						t.Fatal(err)
397					}
398				}
399				store, err := NewFileStore(filepath.Join(repo, tt.rel))
400				if tt.wantError {
401					if err == nil {
402						t.Fatalf("NewFileStore inside a repository that does not ignore the file = %v, want an error", store)
403					}
404					if _, statErr := os.Stat(filepath.Join(repo, tt.rel)); !os.IsNotExist(statErr) {
405						t.Errorf("a refused path was created anyway (stat error = %v)", statErr)
406					}
407					return
408				}
409				if err != nil {
410					t.Fatalf("NewFileStore on an ignored path: %v", err)
411				}
412				if store == nil {
413					t.Fatal("NewFileStore returned a nil store without an error")
414				}
415			})
416		}
417	
418		t.Run("outside any repository: accepted", func(t *testing.T) {
419			gitRepo(t) // only for the isolation of the git configuration
420			outside := t.TempDir()
421			store, err := NewFileStore(filepath.Join(outside, "ctx", "ns", "secrets.json"))
422			if err != nil {
423				t.Fatalf("NewFileStore outside a repository: %v", err)
424			}
425			if store == nil {
426				t.Fatal("NewFileStore returned a nil store without an error")
427			}
428		})
429	}
